fn largest_power_of_two_le(n: i8) -> i8 {
    // Find the largest power of two <= n
    // Start from 1 and keep shifting left while it doesn't exceed n
    // We assume n >= 1 as per problem statement
    let mut power = 1;
    while power <= n / 2 {
        power <<= 1;
    }
    power
}

fn solve(n: i8) -> i8 {
    if n % 2 != 0 {
        // odd case
        (n - 1) / 2
    } else {
        // even case
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}